    let wrappedClient;
    const getBaseClient = () => {
        if (!baseClientPromise) {
            baseClientPromise = loadCapnweb().then((mod) => {
                const session = mod.newWebSocketRpcSession(endpoint);
                if (typeof session.onRpcBroken === "function") {
                    session.onRpcBroken(() => {
