    // before asserting on it.
    async warmUp(endpoint = DEFAULT_SYNCED_STATE_PATH) {
        const normalized = normalizeEndpoint(endpoint);
        const promise = baseClientPromiseByEndpoint.get(normalized);
        if (promise) {
            await promise.catch(() => { });
        }
    },
};

