- `getRequestInfo()` — imperative access
- `requestInfo` — reactive proxy (getter-based)
- Route handler parameter: `route("/path", (requestInfo) => { ... })`

---

## 9. `defineApp()` — The Worker Entry Point

```ts
import { defineApp } from "rwsdk/worker";

export default defineApp([
  // Global middleware
  setCommonHeaders(),

  // Route groups with Document wrapper
  render(Document, [
    route("/", Home),
    route("/about", About),
  ]),
], {
  allowedOrigins: ["https://myapp.com"],  // optional CORS for server actions
});
```

Returns an object with a `fetch(request, env, cf)` method — the standard Cloudflare Workers entry point.

---

## 10. Type-Safe Links

```ts
import { defineLinks } from "rwsdk/router";

const link = defineLinks(["/", "/about", "/users/:id"]);

link("/");              // → "/"
link("/users/:id", { id: "123" });  // → "/users/123"
```

---

## 11. Complete Example Patterns

### Full Worker with Everything

```ts
// src/worker.tsx
import { render, route, prefix, except } from "rwsdk/router";
import { defineApp, serverAction, serverQuery } from "rwsdk/worker";
import { realtimeRoute, renderRealtimeClients } from "rwsdk/realtime/worker";
import { SyncedStateServer, syncedStateRoutes } from "rwsdk/use-synced-state/worker";
import { Document } from "@/app/document";
import { Home } from "@/app/pages/home";

// Set up synced state key scoping
SyncedStateServer.registerKeyHandler(async (key, stub) => {
  const { ctx } = getRequestInfo();
  return ctx.roomId ? `room:${ctx.roomId}:${key}` : key;
});

export default defineApp([
  // Global middleware
  setCommonHeaders(),

  // Realtime WebSocket endpoint
  realtimeRoute((env) => env.REALTIME),

  // Synced state endpoints
  ...syncedStateRoutes((env) => env.SYNCED_STATE),

  // Error handler
  except((error, requestInfo) => {
    console.error("Unhandled error:", error);
    return new Response("Internal Server Error", { status: 500 });
  }),

  // Routes
  render(Document, [
    route("/", Home),
    route("/api/data", {
      get: async () => Response.json({ data: "ok" }),
      post: async ({ request }) => {
        const body = await request.json();
        return Response.json({ received: body }, { status: 201 });
      },
    }),
  ]),
]);
```

### Server Actions with Realtime Updates

```ts
// src/app/actions.ts
"use server";

import { renderRealtimeClients } from "rwsdk/realtime/worker";
import { env } from "cloudflare:workers";

export const addMetric = serverAction(async (name: string, value: number) => {
  // Save to DB or DO...

  // Push update to all connected clients
  await renderRealtimeClients({
    durableObjectNamespace: env.REALTIME,
  });

  return { success: true };
});
```

### Shared State with useSyncedState

```tsx
// src/app/components/MetricsDisplay.tsx
"use client";

import { useSyncedState } from "rwsdk/use-synced-state/client";

export function MetricsDisplay() {
  const [metrics, setMetrics] = useSyncedState<Metric[]>(
    [],
    "dashboard-metrics",
    "room-1"  // optional room scoping
  );

  return (
    <div>
      {metrics.map(m => (
        <div key={m.name}>{m.name}: {m.value}</div>
      ))}
    </div>
  );
}
```

### Wrangler Configuration for DO Bindings

```jsonc
// wrangler.jsonc
{
  "name": "my-app",
  "main": "src/worker.tsx",
  "durable_objects": {
    "bindings": [
      { "name": "REALTIME", "class_name": "RealtimeDurableObject" },
      { "name": "SYNCED_STATE", "class_name": "SyncedStateServer" }
    ]
  },
  "migrations": [
    { "tag": "v1", "new_classes": ["RealtimeDurableObject", "SyncedStateServer"] }
  ]
}
```

