import { DurableObject } from "cloudflare:workers";

// ── Types ───────────────────────────────────────────────────────────────────

export interface Tick {
  seq: number;
  value: number;
  alert: boolean;
}

export interface MetricsState {
  running: boolean;
  seq: number;
  tickCount: number;
  minValue: number | null;
  maxValue: number | null;
  alertCount: number;
  threshold: number | null;
  history: Tick[]; // most recent first
}

interface WSAttachment {
  subscriptions: string[];
}

// ── Constants ───────────────────────────────────────────────────────────────

const MAX_HISTORY = 50;
const TICK_INTERVAL_MS = 1000;
const STORAGE_KEY = "metrics_state";

// ── Durable Object ──────────────────────────────────────────────────────────

export class MetricsDurableObject extends DurableObject {
  private state_: MetricsState | null = null;

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
  }

  // ── HTTP API ────────────────────────────────────────────────────────────

  async fetch(request: Request): Promise<Response> {
    const url = new URL(request.url);
    const path = url.pathname;

    // WebSocket upgrade for live state streaming
    if (path === "/ws") {
      return this.handleWebSocketUpgrade();
    }

    // HTTP API endpoints
    if (path === "/start") return this.handleStart();
    if (path === "/stop") return this.handleStop();
    if (path === "/set-threshold" && request.method === "POST") {
      const body: { threshold: number } = await request.json();
      return this.handleSetThreshold(body.threshold);
    }
    if (path === "/state") return this.handleGetState();

    return new Response("Not Found", { status: 404 });
  }

  // ── WebSocket (Hibernation API) ─────────────────────────────────────────

  private handleWebSocketUpgrade(): Response {
    const { 0: client, 1: server } = new WebSocketPair();
    const attachment: WSAttachment = { subscriptions: ["state"] };
    server.serializeAttachment(attachment);
    this.ctx.acceptWebSocket(server);
    return new Response(null, { status: 101, webSocket: client });
  }

  async webSocketMessage(ws: WebSocket, data: string | ArrayBuffer): Promise<void> {
    // Clients don't send messages in this protocol; they just listen.
    // But we handle ping/pong or any future commands here.
  }

  async webSocketClose(_ws: WebSocket): Promise<void> {
    // No cleanup needed; subscriptions live on the attachment.
  }

  async webSocketError(_ws: WebSocket, _error: Error): Promise<void> {
    // No-op
  }

  // ── Alarm (Tick Timer) ──────────────────────────────────────────────────

  async alarm(): Promise<void> {
    const state = await this.getState();
    if (!state.running) return;

    // Produce a tick
    const seq = state.seq + 1;
    const value = Math.floor(Math.random() * 100) + 1;

    // Determine if this is an alert
    const isAlert = state.threshold !== null && value > state.threshold;

    const tick: Tick = { seq, value, alert: isAlert };

    // Update counters
    state.seq = seq;
    state.tickCount = state.tickCount + 1;
    state.minValue =
      state.minValue === null ? value : Math.min(state.minValue, value);
    state.maxValue =
      state.maxValue === null ? value : Math.max(state.maxValue, value);
    if (isAlert) {
      state.alertCount = state.alertCount + 1;
    }

    // Update history (keep most recent at the front)
    state.history.unshift(tick);
    if (state.history.length > MAX_HISTORY) {
      state.history = state.history.slice(0, MAX_HISTORY);
    }

    await this.saveState(state);

    // Broadcast to all connected WebSocket clients
    this.broadcastState(state);

    // Schedule next tick
    if (state.running) {
      await this.ctx.storage.setAlarm(Date.now() + TICK_INTERVAL_MS);
    }
  }

  // ── State Management ────────────────────────────────────────────────────

  private async getState(): Promise<MetricsState> {
    if (this.state_) return this.state_;

    const stored = await this.ctx.storage.get<MetricsState>(STORAGE_KEY);
    if (stored) {
      this.state_ = stored;
      return stored;
    }

    // Default initial state
    const initial: MetricsState = {
      running: false,
      seq: 0,
      tickCount: 0,
      minValue: null,
      maxValue: null,
      alertCount: 0,
      threshold: null,
      history: [],
    };
    this.state_ = initial;
    return initial;
  }

  private async saveState(state: MetricsState): Promise<void> {
    this.state_ = state;
    await this.ctx.storage.put(STORAGE_KEY, state);
  }

  // ── Broadcast ───────────────────────────────────────────────────────────

  private broadcastState(state: MetricsState): void {
    const payload = JSON.stringify({ kind: "state", state });
    for (const ws of this.ctx.getWebSockets()) {
      try {
        ws.send(payload);
      } catch {
        // Socket already closed
      }
    }
  }

  // ── Handlers ────────────────────────────────────────────────────────────

  private async handleStart(): Promise<Response> {
    const state = await this.getState();
    if (!state.running) {
      state.running = true;
      await this.saveState(state);
      // Schedule first tick
      await this.ctx.storage.setAlarm(Date.now() + TICK_INTERVAL_MS);
      this.broadcastState(state);
    }
    return Response.json({ success: true, running: true });
  }

  private async handleStop(): Promise<Response> {
    const state = await this.getState();
    if (state.running) {
      state.running = false;
      await this.saveState(state);
      await this.ctx.storage.deleteAlarm();
      this.broadcastState(state);
    }
    return Response.json({ success: true, running: false });
  }

  private async handleSetThreshold(threshold: number): Promise<Response> {
    const state = await this.getState();
    state.threshold = threshold;
    await this.saveState(state);
    this.broadcastState(state);
    return Response.json({ success: true, threshold });
  }

  private async handleGetState(): Promise<Response> {
    const state = await this.getState();
    return Response.json(state);
  }
}

"use server";

import { serverAction } from "rwsdk/worker";
import { env } from "cloudflare:workers";

export const startStream = serverAction(async () => {
  const id = env.METRICS.idFromName("shared");
  const stub = env.METRICS.get(id);
  const response = await stub.fetch("https://do/start");
  return response.json();
});

export const stopStream = serverAction(async () => {
  const id = env.METRICS.idFromName("shared");
  const stub = env.METRICS.get(id);
  const response = await stub.fetch("https://do/stop");
  return response.json();
});

export const applyThreshold = serverAction(async (threshold: number) => {
  const id = env.METRICS.idFromName("shared");
  const stub = env.METRICS.get(id);
  const response = await stub.fetch("https://do/set-threshold", {
    method: "POST",
    body: JSON.stringify({ threshold }),
  });
  return response.json();
});

export const getMetricsState = serverAction(async () => {
  const id = env.METRICS.idFromName("shared");
  const stub = env.METRICS.get(id);
  const response = await stub.fetch("https://do/state");
  return response.json();
});

"use client";

import { useState, useEffect, useRef, useCallback } from "react";
import type { MetricsState, Tick } from "./metrics-do";

// ── Helpers ─────────────────────────────────────────────────────────────────

function getWebSocketUrl(): string {
  // In dev, the worker runs on the same origin
  const proto = location.protocol === "https:" ? "wss:" : "ws:";
  return `${proto}//${location.host}/metrics/ws`;
}

// ── Component ───────────────────────────────────────────────────────────────

export function MetricsPage() {
  const [state, setState] = useState<MetricsState>({
    running: false,
    seq: 0,
    tickCount: 0,
    minValue: null,
    maxValue: null,
    alertCount: 0,
    threshold: null,
    history: [],
  });
  const [thresholdInput, setThresholdInput] = useState("");
  const wsRef = useRef<WebSocket | null>(null);
  const mountedRef = useRef(true);

  // Connect to WebSocket for live state
  useEffect(() => {
    mountedRef.current = true;

    function connect() {
      const ws = new WebSocket(getWebSocketUrl());
      wsRef.current = ws;

      ws.onmessage = (event) => {
        if (!mountedRef.current) return;
        try {
          const data = JSON.parse(event.data);
          if (data.kind === "state" && data.state) {
            setState(data.state);
          }
        } catch {
          // ignore parse errors
        }
      };

      ws.onclose = () => {
        if (!mountedRef.current) return;
        // Reconnect after 1 second
        setTimeout(() => {
          if (mountedRef.current) connect();
        }, 1000);
      };

      ws.onerror = () => {
        ws.close();
      };
    }

    connect();

    return () => {
      mountedRef.current = false;
      wsRef.current?.close();
    };
  }, []);

  // ── Actions ─────────────────────────────────────────────────────────────

  const handleStart = useCallback(async () => {
    try {
      const resp = await fetch("/metrics/start", { method: "POST" });
      await resp.json();
    } catch (e) {
      console.error("Start failed:", e);
    }
  }, []);

  const handleStop = useCallback(async () => {
    try {
      const resp = await fetch("/metrics/stop", { method: "POST" });
      await resp.json();
    } catch (e) {
      console.error("Stop failed:", e);
    }
  }, []);

  const handleApplyThreshold = useCallback(async () => {
    const val = parseInt(thresholdInput, 10);
    if (isNaN(val)) return;
    try {
      const resp = await fetch("/metrics/set-threshold", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ threshold: val }),
      });
      await resp.json();
    } catch (e) {
      console.error("Set threshold failed:", e);
    }
  }, [thresholdInput]);

  // ── Derived values ─────────────────────────────────────────────────────

  const latestTick: Tick | null =
    state.history.length > 0 ? state.history[0] : null;

  const isOverThreshold =
    state.threshold !== null &&
    latestTick !== null &&
    latestTick.value > state.threshold;

  // ── Render ──────────────────────────────────────────────────────────────

  return (
    <div style={{ fontFamily: "system-ui, sans-serif", padding: "2rem", maxWidth: "800px", margin: "0 auto" }}>
      <h1>Metrics Dashboard</h1>

      {/* Controls */}
      <div style={{ marginBottom: "1.5rem", display: "flex", gap: "0.5rem", alignItems: "center", flexWrap: "wrap" }}>
        <button
          data-testid="start-stream"
          onClick={handleStart}
          disabled={state.running}
          style={{ padding: "0.5rem 1rem", cursor: state.running ? "not-allowed" : "pointer" }}
        >
          Start Stream
        </button>
        <button
          data-testid="stop-stream"
          onClick={handleStop}
          disabled={!state.running}
          style={{ padding: "0.5rem 1rem", cursor: !state.running ? "not-allowed" : "pointer" }}
        >
          Stop Stream
        </button>
        <input
          data-testid="threshold-input"
          type="number"
          value={thresholdInput}
          onChange={(e) => setThresholdInput(e.target.value)}
          placeholder="Threshold"
          style={{ padding: "0.5rem", width: "120px" }}
        />
        <button
          data-testid="apply-threshold"
          onClick={handleApplyThreshold}
          style={{ padding: "0.5rem 1rem" }}
        >
          Apply Threshold
        </button>
      </div>

      {/* Widgets */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))", gap: "1rem", marginBottom: "1.5rem" }}>
        <div style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "1rem", textAlign: "center" }}>
          <div style={{ fontSize: "0.85rem", color: "#666", marginBottom: "0.25rem" }}>Current Value</div>
          <div
            data-testid="current-value"
            {...(isOverThreshold ? { "data-over": "true" } : {})}
            style={{ fontSize: "2rem", fontWeight: "bold", color: isOverThreshold ? "#e53e3e" : "#333" }}
          >
            {latestTick !== null ? latestTick.value : "-"}
          </div>
        </div>
        <div style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "1rem", textAlign: "center" }}>
          <div style={{ fontSize: "0.85rem", color: "#666", marginBottom: "0.25rem" }}>Tick Count</div>
          <div data-testid="tick-count" style={{ fontSize: "2rem", fontWeight: "bold" }}>
            {state.tickCount}
          </div>
        </div>
        <div style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "1rem", textAlign: "center" }}>
          <div style={{ fontSize: "0.85rem", color: "#666", marginBottom: "0.25rem" }}>Min Value</div>
          <div data-testid="min-value" style={{ fontSize: "2rem", fontWeight: "bold" }}>
            {state.minValue !== null ? state.minValue : "-"}
          </div>
        </div>
        <div style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "1rem", textAlign: "center" }}>
          <div style={{ fontSize: "0.85rem", color: "#666", marginBottom: "0.25rem" }}>Max Value</div>
          <div data-testid="max-value" style={{ fontSize: "2rem", fontWeight: "bold" }}>
            {state.maxValue !== null ? state.maxValue : "-"}
          </div>
        </div>
        <div style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "1rem", textAlign: "center" }}>
          <div style={{ fontSize: "0.85rem", color: "#666", marginBottom: "0.25rem" }}>Alert Count</div>
          <div data-testid="alert-count" style={{ fontSize: "2rem", fontWeight: "bold", color: "#e53e3e" }}>
            {state.alertCount}
          </div>
        </div>
      </div>

      {/* History */}
      <div>
        <h2 style={{ fontSize: "1.1rem", marginBottom: "0.5rem" }}>Recent Ticks</h2>
        <div
          data-testid="history"
          style={{
            border: "1px solid #ccc",
            borderRadius: "8px",
            maxHeight: "400px",
            overflowY: "auto",
            padding: "0.5rem",
          }}
        >
          {state.history.length === 0 ? (
            <div style={{ color: "#999", padding: "1rem", textAlign: "center" }}>
              No ticks yet. Start the stream to begin.
            </div>
          ) : (
            state.history.map((tick) => (
              <div
                key={tick.seq}
                data-testid={`tick-${tick.seq}`}
                data-seq={tick.seq}
                data-value={tick.value}
                {...(tick.alert ? { "data-alert": "true" } : {})}
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  padding: "0.4rem 0.5rem",
                  borderBottom: "1px solid #eee",
                  backgroundColor: tick.alert ? "#fff5f5" : "transparent",
                  borderRadius: tick.alert ? "4px" : undefined,
                }}
              >
                <span style={{ fontWeight: "bold" }}>#{tick.seq}</span>
                <span style={{ color: tick.alert ? "#e53e3e" : "#333" }}>
                  {tick.value}
                  {tick.alert ? " ⚠" : ""}
                </span>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

import { render, route } from "rwsdk/router";
import { defineApp } from "rwsdk/worker";

import { Document } from "@/app/document";
import { setCommonHeaders } from "@/app/headers";
import { Home } from "@/app/pages/home";
import { MetricsPage } from "@/app/metrics/metrics-page";
import { MetricsDurableObject } from "@/app/metrics/metrics-do";

export type AppContext = {};

export { MetricsDurableObject };

export default defineApp([
  setCommonHeaders(),
  render(Document, [
    route("/", Home),

    // Metrics dashboard page
    route("/metrics", () => <MetricsPage />),

    // Metrics API endpoints (proxied to the Durable Object)
    route("/metrics/ws", ({ request, env }) => {
      const id = env.METRICS.idFromName("shared");
      const stub = env.METRICS.get(id);
      // Forward the WebSocket upgrade request to the DO
      return stub.fetch(
        new Request(new URL("/ws", request.url), request)
      );
    }),
    route("/metrics/start", {
      post: async ({ env }) => {
        const id = env.METRICS.idFromName("shared");
        const stub = env.METRICS.get(id);
        return stub.fetch("https://do/start");
      },
    }),
    route("/metrics/stop", {
      post: async ({ env }) => {
        const id = env.METRICS.idFromName("shared");
        const stub = env.METRICS.get(id);
        return stub.fetch("https://do/stop");
      },
    }),
    route("/metrics/set-threshold", {
      post: async ({ request, env }) => {
        const id = env.METRICS.idFromName("shared");
        const stub = env.METRICS.get(id);
        return stub.fetch("https://do/set-threshold", {
          method: "POST",
          body: JSON.stringify(await request.json()),
        });
      },
    }),
    route("/metrics/state", {
      get: async ({ env }) => {
        const id = env.METRICS.idFromName("shared");
        const stub = env.METRICS.get(id);
        return stub.fetch("https://do/state");
      },
    }),
  ]),
]);

